122	
123				if (!replacementValue) return;
124	
125				const firstKeyword = keywords.at(0);
126				const lastKeyword = keywords.at(-1);
127	
128				if (!firstKeyword || !lastKeyword) return;
129	
130				const index = declarationValueIndex(decl);
131	
132				report({
133					message: messages.expected,
134					messageArgs: [normalizedValue, replacementValue.join(' ')],
