154	/**
155	 * @param {string} a
156	 * @returns {number}
157	 */
158	function keywordOrder(a) {
159		if (DISPLAY_OUTSIDE.test(a)) return 1;
160	
161		if (DISPLAY_INSIDE.test(a)) return 2;
162	
163		if (DISPLAY_LIST_ITEM.test(a)) return 3;
