177	/**
178	 * @param {Array<TokenIdent>} tokens
179	 * @returns {string}
180	 */
181	function normalizeValue(tokens) {
182		return tokens
183			.map((token) => token[4].value)
184			.sort(compareKeywords)
185			.join(' ')
186			.toLowerCase();
187	}
