189	/**
190	 * @param {Array<CSSToken>} originalValue
191	 * @param {TokenIdent} firstKeyword
192	 * @param {TokenIdent} lastKeyword
193	 * @param {Array<string>} replacement
194	 * @returns {string}
195	 */
196	function fixValue(originalValue, firstKeyword, lastKeyword, replacement) {
197		const before = originalValue.slice(0, originalValue.indexOf(firstKeyword));
198		const commentsBetweenKeywords = originalValue
199			.slice(originalValue.indexOf(firstKeyword), originalValue.indexOf(lastKeyword))
200			.filter(isTokenComment);
201		const after = originalValue.slice(originalValue.indexOf(lastKeyword) + 1);
202	
203		return stringify(
204			...before,
205			...replacement.flatMap((keyword, index) => {
206				/** @type {Array<CSSToken>} */
207				const tokens = [];
208	
209				if (index !== 0) {
210					tokens.push([TokenType.Whitespace, ' ', -1, -1, undefined]);
211				}
212	
213				tokens.push([TokenType.Ident, keyword, -1, -1, { value: keyword }]);
214	
215				return tokens;
216			}),
217			...commentsBetweenKeywords,
218			...after,
219		);
220	}
